#[cfg(test)]
mod tests {
    use super::ALIASES;
    use crate::{FormulaLocale, parse, parse_input, print, print_input};

    #[test]
    fn every_hungarian_alias_is_unique_and_round_trips() {
        let mut names = std::collections::HashSet::new();
        for &(canonical, localized) in ALIASES {
            assert!(names.insert(localized), "ambiguous alias: {localized}");
            let expr = parse(&format!("{canonical}(A1)")).unwrap();
            let shown = print_input(&expr, FormulaLocale::Hu, |_| false).unwrap();
            assert_eq!(shown, format!("{localized}(A1)"));
            let restored = parse_input(&shown.to_lowercase(), FormulaLocale::Hu, |_| false).unwrap();
            assert_eq!(print(&restored), print(&expr), "{localized}");
        }
    }
}
